import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Header from "../../components/Header/Header";
import Footer from "../../components/Footer/Footer";
import "./result-list-page.css";

const ResultListPage: React.FC = () => {
  const [testData, setTestData] = useState({
    incomplete_tests: [],
    tests_with_pending_results: [],
    tests_with_results: [],
  });
  const [message, setMessage] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState("incomplete");
  const navigate = useNavigate();

  useEffect(() => {
    const fetchTestData = async () => {
      try {
        const rollno = localStorage.getItem("userEmail");
        if (!rollno) {
          setMessage("Roll number not found. Please log in.");
          return;
        }

        const response = await fetch("http://localhost:5000/resultlist", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ rollno }),
        });

        if (response.ok) {
          const data = await response.json();
          setTestData(data);
        } else {
          const error = await response.json();
          setMessage(`Error: ${error.error}`);
        }
      } catch (err) {
        setMessage(`Error: ${err}`);
      }
    };

    fetchTestData();
    const interval = setInterval(fetchTestData, 5000);
    return () => clearInterval(interval);
  }, []);

  const handleAction = (testId: number, action: string) => {
    if (action === "view_result") {
      localStorage.setItem("test_id", testId.toString());
      navigate("/completion-page");
    }
  };

  return (
    <div className="App">
      <Header />
      <div className="result-container">
        <h2>Test Status</h2>
        {message && <p className="feedback-message">{message}</p>}
        {testData[activeTab].map((test) => (
          <div key={test.test_id} className="test-item">
            <span>Test ID: {test.test_id}</span>
            <span>Created At: {test.created_at}</span>
            <button onClick={() => handleAction(test.test_id, "view_result")}>View Result</button>
          </div>
        ))}
      </div>
      <Footer />
    </div>
  );
};

export default ResultListPage;
